    {
      "rank": 1,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Alan H. Guth",
        "Andrei Linde",
        "Viatcheslav Mukhanov"
      ],
      "assessment": {
        "nobel_worthiness": "Inflation and the quantum origin of cosmic structure supplied a remarkably fertile physical framework for the early universe and its observable consequences.",
        "attribution": "Guth initiated inflation, Linde developed decisive realizations of it, and Mukhanov established the quantum-fluctuation mechanism central to its predictive content.",
        "maturity": "CMB observations strongly support the broad inflationary account and its structure-formation predictions after decades of scrutiny.",
        "uncertainties": [
          "No particular inflationary model has been uniquely selected by observation.",
          "A direct primordial gravitational-wave signature remains absent."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Daniel J. Eisenstein",
        "Matthew Colless",
        "Shaun Cole"
      ],
      "assessment": {
        "nobel_worthiness": "Establishing baryon acoustic oscillations as a standard ruler made the expansion history of the universe measurable with exceptional robustness.",
        "attribution": "Eisenstein and the 2dF/SDSS observational leadership represented by Colless and Cole capture key theoretical and survey contributions.",
        "maturity": "The ruler has been repeatedly detected and refined by independent galaxy surveys and is now foundational to precision cosmology.",
        "uncertainties": [
          "The achievement rests on extensive survey collaborations, making individual attribution necessarily selective."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B029",
      "proposed_laureates": [
        "Heino Falcke",
        "Ramesh Narayan",
        "Sheperd S. Doeleman"
      ],
      "assessment": {
        "nobel_worthiness": "The first horizon-scale black-hole images transformed a long-standing theoretical object into an extraordinary observational target.",
        "attribution": "Falcke and Narayan supplied influential shadow science and interpretation, while Doeleman led the interferometric route that made the measurement possible.",
        "maturity": "Independent images of M87* and Sgr A* and continuing horizon-scale observations establish this as a durable observational achievement.",
        "uncertainties": [
          "The images are reconstructed interferometrically and their detailed interpretation remains model dependent.",
          "The decisive work involved a very large collaboration."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B021",
      "proposed_laureates": [
        "Francis Halzen",
        "Christian Spiering",
        "Albrecht Karle"
      ],
      "assessment": {
        "nobel_worthiness": "IceCube opened high-energy neutrino astronomy, adding a genuinely new messenger for the violent universe.",
        "attribution": "Halzen, Spiering, and Karle represent conception, construction, and scientific realization of the observatory.",
        "maturity": "The diffuse extraterrestrial flux is secure, with accumulating source associations and multi-messenger results.",
        "uncertainties": [
          "Individual source identification remains incomplete.",
          "Attribution must stand for the much larger IceCube collaboration."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B032",
      "proposed_laureates": [
        "Charles L. Bennett",
        "David N. Spergel",
        "Lyman A. Page"
      ],
      "assessment": {
        "nobel_worthiness": "WMAP turned the cosmic microwave background into a precision probe of the universe's composition, age, geometry, and primordial fluctuations.",
        "attribution": "Bennett and Page led the experimental mission, while Spergel was central to extracting its cosmological physical meaning.",
        "maturity": "Its conclusions were independently sharpened by later CMB measurements and remain integral to the standard cosmological model.",
        "uncertainties": [
          "The discovery is inseparable from a substantial mission team.",
          "Some cosmological parameter tensions limit any claim of a wholly closed model."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B017",
      "proposed_laureates": [
        "Maura McLaughlin",
        "Michael Kramer",
        "Xavier Siemens"
      ],
      "assessment": {
        "nobel_worthiness": "The pulsar-timing detection of a nanohertz gravitational-wave background extends gravitational-wave astronomy to an entirely new frequency range.",
        "attribution": "These scientists represent major leadership across the observational collaborations and the interpretation of the common signal.",
        "maturity": "Multiple pulsar timing arrays report consistent evidence, making the signal compelling rather than a single-experiment anomaly.",
        "uncertainties": [
          "The source population and detailed spectral interpretation are still being resolved.",
          "The result is recent and rests on broad international collaborations."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B006",
      "proposed_laureates": [
        "Ewine F. van Dishoeck",
        "Alexander G. G. M. Tielens",
        "Eric Herbst"
      ],
      "assessment": {
        "nobel_worthiness": "This work made molecular chemistry a quantitative part of the account of how stars, disks, and potentially habitable planetary environments form.",
        "attribution": "Van Dishoeck, Tielens, and Herbst represent complementary observational, molecular-physics, and chemical-network foundations.",
        "maturity": "Decades of spectroscopy, laboratory work, and space observations have made the field experimentally rich and broadly influential.",
        "uncertainties": [
          "The contribution is a wide body of work rather than one sharply bounded discovery.",
          "Individual priority across astrochemistry is difficult to delimit."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B054",
      "proposed_laureates": [
        "Andrew Strominger",
        "Cumrun Vafa",
        "Juan Maldacena"
      ],
      "assessment": {
        "nobel_worthiness": "Microscopic accounting of black-hole entropy was a profound advance toward reconciling quantum theory, gravity, and holography.",
        "attribution": "Strominger and Vafa achieved the landmark microstate calculation, while Maldacena supplied central subsequent holographic insight.",
        "maturity": "Its theoretical influence is immense and enduring, but it has not yet acquired a direct empirical foothold.",
        "uncertainties": [
          "The result is established most cleanly in special string-theory settings rather than realistic astrophysical black holes.",
          "There is no direct experimental confirmation of the underlying quantum-gravity framework."
        ]
      }
    }
  ]
}
